#include <arpa/inet.h>
#include <netinet/in.h>
#include <stdio.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void) {
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    int one = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(9000)};
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(srv, (struct sockaddr *)&addr, sizeof addr);   /* claim address and port */
    listen(srv, 5);                                      /* start accepting; backlog 5 */

    int c = accept(srv, NULL, NULL);                     /* wait for one client */
    char buf[64];
    ssize_t n = read(c, buf, sizeof buf - 1);
    buf[n > 0 ? n : 0] = 0;
    printf("server got: %s", buf);
    write(c, "pong\n", 5);
    close(c);
    close(srv);
    return 0;
}

#include <arpa/inet.h>
#include <netinet/in.h>
#include <stdio.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void) {
    int s = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(9000)};
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    connect(s, (struct sockaddr *)&addr, sizeof addr);   /* the three-way handshake happens here */
    write(s, "ping\n", 5);
    char buf[16];
    ssize_t n = read(s, buf, sizeof buf - 1);
    buf[n > 0 ? n : 0] = 0;
    printf("client got: %s", buf);
    close(s);
    return 0;
}

